#!/usr/bin/env python3
"""Restore binary assets (icons + sample CBZ) into the repo tree."""
import base64, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[1]
ASSETS = {
  "assets/manga-reel-icon.png": "",
  "icons/hicolor/128x128/apps/manga-reel.png": "",
  "icons/hicolor/16x16/apps/manga-reel.png": "",
  "icons/hicolor/256x256/apps/manga-reel.png": "",
  "icons/hicolor/32x32/apps/manga-reel.png": "",
  "icons/hicolor/48x48/apps/manga-reel.png": "",
  "testdata/sample-panels.cbz": ""
}
def main():
    for rel, b64 in ASSETS.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(b64))
        print("wrote", path, path.stat().st_size)
if __name__ == "__main__":
    main()
